const searchConversationMessages = `-- name: SearchConversationMessages :many
SELECT id, ordinal, conversation_id, cycle_id, sender_type, sender_bot_id, content, metadata, client_msg_id, run_id, created_at, parent_message_id, edited_at, deleted_at, pinned_at FROM messages
WHERE conversation_id = $1 AND deleted_at IS NULL
  AND content ILIKE '%' || $2::text || '%'
ORDER BY ordinal DESC
LIMIT $3
`

type SearchConversationMessagesParams struct {
	ConversationID uuid.UUID `json:"conversation_id"`
	Query          string    `json:"query"`
	MaxRows        int32     `json:"max_rows"`
}

func (q *Queries) SearchConversationMessages(ctx context.Context, arg SearchConversationMessagesParams) ([]Message, error) {
	rows, err := q.db.Query(ctx, searchConversationMessages, arg.ConversationID, arg.Query, arg.MaxRows)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Message{}
	for rows.Next() {
		var i Message
		if err := rows.Scan(
			&i.ID,
			&i.Ordinal,
			&i.ConversationID,
			&i.CycleID,
			&i.SenderType,
			&i.SenderBotID,
			&i.Content,
			&i.Metadata,
			&i.ClientMsgID,
			&i.RunID,
			&i.CreatedAt,
			&i.ParentMessageID,
			&i.EditedAt,
			&i.DeletedAt,
			&i.PinnedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

